module pid_algorithm(
	clk,
	rstn,
	error_cur,
	error_last,
	sum_e,
	kp,
	ki,
	kd,
	ctrl_out);

	//---Ports declearation: generated by Robei---
	input clk;
	input rstn;
	input [31:0] error_cur;
	input [31:0] error_last;
	input [31:0] sum_e;
	input [7:0] kp;
	input [7:0] ki;
	input [7:0] kd;
	output [63:0] ctrl_out;

	wire clk;
	wire rstn;
	wire [31:0] error_cur;
	wire [31:0] error_last;
	wire [31:0] sum_e;
	wire [7:0] kp;
	wire [7:0] ki;
	wire [7:0] kd;
	reg [63:0] ctrl_out;

	//----Code starts here: integrated by Robei-----
	 always @(posedge clk or negedge rstn) begin
	        if(! rstn) begin
	            ctrl_out <= 64'd0;
	        end
	        else begin
	            ctrl_out <= (kp*error_cur) + (ki*sum_e) + (kd*(error_cur - error_last));    // PID计算
	        end
	end
	
	
	
endmodule    //pid_algorithm

